syntax:
// type name;                 -> declare (make the box)
int marks;

// type name = value;          -> declare and initialise
int age = 20;
double price = 99.5;
char grade = 'A';            // one character: single quotes
bool passed = true;          // true or false
string name = "Ali";        // text: double quotes (#include <string>)

// const type NAME = value;    -> constant, cannot change
const double PI = 3.14159;

// sizeof tells the size in bytes
cout << sizeof(int);         // prints 4

// Identifier rules: letters, digits, _ only;
// cannot start with a digit; cannot be a keyword.

sample.code:
#include <iostream>
#include <string>
using namespace std;

int main() {
    int marks = 85;
    double price = 99.5;
    char grade = 'A';
    bool passed = true;
    string name = "Ali";
    cout << name << " " << marks << " " << grade << endl;
    cout << price << " " << passed << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const double TAX = 0.10;
    double price = 500;
    double total;
    total = price + price * TAX;
    cout << "Total = " << total << endl;
    price = 800;
    cout << "New price = " << price << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string name = "Sara";
    int age = 18;
    double cgpa = 3.5;
    char section = 'V';
    cout << "Name: " << name << endl;
    cout << "Age: " << age << endl;
    cout << "CGPA: " << cgpa << endl;
    cout << "Section: " << section << endl;
    cout << "int uses " << sizeof(int) << " bytes" << endl;
    cout << "double uses " << sizeof(double) << " bytes" << endl;
    cout << "char uses " << sizeof(char) << " bytes" << endl;
    return 0;
}

